using System;
// Sparse backward-Euler balance. Only actual neighbour links are visited.
internal sealed class ClimateBalanceSolver {
internal readonly int[] A,B;internal readonly double[] G,Base,Rhs,X;
readonly double[] diagonal,r,z,p,q,scaledG;readonly double seconds;
internal ClimateBalanceSolver(int count,int[] a,int[] b,double[] g,double dt){A=a;B=b;G=g;seconds=dt;Base=new double[count];Rhs=new double[count];X=new double[count];diagonal=new double[count];r=new double[count];z=new double[count];p=new double[count];q=new double[count];scaledG=new double[g.Length];for(int j=0;j<g.Length;j++)scaledG[j]=dt*g[j];}
void Multiply(double[] x,double[] y){for(int i=0;i<x.Length;i++)y[i]=Base[i]*x[i];for(int j=0;j<G.Length;j++){double transfer=scaledG[j]*(x[A[j]]-x[B[j]]);y[A[j]]+=transfer;y[B[j]]-=transfer;}}
internal int Solve(double tolerance,int iterations){Array.Copy(Base,diagonal,Base.Length);for(int j=0;j<G.Length;j++){diagonal[A[j]]+=scaledG[j];diagonal[B[j]]+=scaledG[j];}Multiply(X,q);double norm=0,rz=0;for(int i=0;i<X.Length;i++){if(!(diagonal[i]>0))throw new InvalidOperationException("Non-positive climate balance diagonal");r[i]=Rhs[i]-q[i];z[i]=r[i]/diagonal[i];p[i]=z[i];norm+=Rhs[i]*Rhs[i];rz+=r[i]*z[i];}double threshold=Math.Max(1e-40,norm*tolerance*tolerance);for(int k=0;k<=iterations;k++){double residual=0;for(int i=0;i<X.Length;i++)residual+=r[i]*r[i];if(residual<=threshold)return k;if(k==iterations)break;Multiply(p,q);double pq=0;for(int i=0;i<X.Length;i++)pq+=p[i]*q[i];if(!(pq>0))throw new InvalidOperationException("Climate balance lost positive definiteness");double alpha=rz/pq,next=0;for(int i=0;i<X.Length;i++){X[i]+=alpha*p[i];r[i]-=alpha*q[i];z[i]=r[i]/diagonal[i];next+=r[i]*z[i];}double beta=next/rz;for(int i=0;i<X.Length;i++)p[i]=z[i]+beta*p[i];rz=next;}throw new InvalidOperationException("Climate balance did not converge");}
}
